    private static void session() {
        byte[] reply1 = FairPlay.setup(FP_SETUP1_REQUEST);
        check(reply1.length == 142 && reply1[14] == 15 && reply1[141] == -70, "fp-setup 1 reply");
        assertArrayEquals(FP_SETUP2_RESPONSE, FairPlay.setup(FP_SETUP2_REQUEST));
        for (int mode = 0; mode < 4; mode++) {
            byte[] request = FP_SETUP1_REQUEST.clone();
            request[14] = (byte) mode;
            byte[] reply = FairPlay.setup(request);
            check(reply.length == 142 && reply[13] == mode, "fp-setup 1 reply for mode " + mode);
        }
        check(FairPlay.decryptKey(FP_SETUP2_REQUEST, EKEY).length == 16, "ekey decrypt");
    }

