    // MARK: - Assertions

    private static void check(boolean ok, String what) {
        if (!ok) throw new AssertionError("FairPlay vector failed: " + what);
        checks++;
    }

    static void assertArrayEquals(byte[] expected, byte[] actual) {
        check(Arrays.equals(expected, actual), "bytes " + Arrays.toString(actual));
    }

    static void assertArrayEquals(int[] expected, int[] actual) {
        check(Arrays.equals(expected, actual), "words " + Arrays.toString(actual));
    }
